            'lg' => '/dummy/media/artikel/Seskab-Teddy-Ungkap-Arahan-Presiden-Prabowo-dalam-Sidang-Kabinet-Paripurna-Perkuat-Ketahanan-Nasional-hingga-Tindak-Tega-lg.webp',
            'sm' => '/dummy/media/artikel/Seskab-Teddy-Ungkap-Arahan-Presiden-Prabowo-dalam-Sidang-Kabinet-Paripurna-Perkuat-Ketahanan-Nasional-hingga-Tindak-Tega-sm.webp',
