        'image' => [
            'lg' => '/dummy/media/artikel/2-TAHUN-PRABOWO-BOLEHKAH-RAKYAT-KECEWA-1_jpg-lg.webp',
            'sm' => '/dummy/media/artikel/2-TAHUN-PRABOWO-BOLEHKAH-RAKYAT-KECEWA-1_jpg-sm.webp',
