            'water-mist',
        ],
        'image' => [
            'lg' => '/dummy/media/artikel/pengoperasian-water-mist-di-atas-gedung-jakarta-2859153-lg.webp',
            'sm' => '/dummy/media/artikel/pengoperasian-water-mist-di-atas-gedung-jakarta-2859153-sm.webp',
            'w' => 800,
