        'image' => [
            'lg' => '/dummy/media/artikel/Menyoroti-RUU-Perampasan-Aset-bagian-3-Siapa-yang-Harus-Membuktikan-lg.webp',
            'sm' => '/dummy/media/artikel/Menyoroti-RUU-Perampasan-Aset-bagian-3-Siapa-yang-Harus-Membuktikan-sm.webp',
