        'image' => [
            'lg' => '/dummy/media/artikel/Menyoroti-RUU-Perampasan-Aset-bagian-2-Aset-Bisa-Dirampas-Tanpa-Putusan-Bersalah-lg.webp',
            'sm' => '/dummy/media/artikel/Menyoroti-RUU-Perampasan-Aset-bagian-2-Aset-Bisa-Dirampas-Tanpa-Putusan-Bersalah-sm.webp',
