        'image' => [
            'lg' => '/dummy/media/artikel/8bc7588ecf4fc0b7ebd856ec78a7e2e2-lg.webp',
            'sm' => '/dummy/media/artikel/8bc7588ecf4fc0b7ebd856ec78a7e2e2-sm.webp',
